INSERT INTO feature VALUES('identity-types','identity','Identity types (Path)',NULL,'implemented','uncommon','mainstream languages','`Path(a, b)` is the type of identifications between two elements, its carrier the type the endpoints fix, checked by the core and persisted by the kernel. Where the endpoints do not fix the carrier, a source supplies it by name, `Path[.A = A](a, b)`, or from the variable `A`, `Path[.A](a, b)`; a carrier written first is refused.','core-checker kernel-core kernel-term surface-lowering','corpus/model/identity/here-formation.gandr corpus/model/identity/carrier-by-name.gandr corpus/pathological/identity/carrier-by-name.gandr','corpus/ledger/features/identity-types.gandr',NULL);
